firecrawl scrape "https://www.sos.ca.gov/business-programs/bizfile" -o .firecrawl/s.md >/dev/null 2>&1; firecrawl interact -c '
const r = await page.goto("https://bizfileonline.sos.ca.gov/search/business",{timeout:25000,waitUntil:"domcontentloaded"}).catch(e=>null);
